humanos em todo o território cearense para posterior\nencaminhamento ao Ministério Público, a fim de que seja\npromovida a responsabilidade dos infratores.\nAssinale\nA) se apenas as afirmativas I e II estiverem corretas.\nB) se apenas as afirmativas I e III estiverem corretas.\nC) se apenas as afirmativas II e III estiverem corretas.\nD) se todas as afirmativas estiverem corretas.\nE) se nenhuma afirmativa estiver correta.","item_number":98,"source_pages":[27],"answer_in_official_document":"A","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":true,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"98. Com base no que reza a Constituição do Estado do Ceará,\nanalise as afirmativas a seguir:\nI. O Poder Executivo instituirá, na forma da lei, a Controladoria-\nGeral de Disciplina dos Órgãos de Segurança Pública e\nSistema Penitenciário, de controle externo disciplinar, com\nautonomia administrativa e financeira, com objetivo exclusivo\nde apurar a responsabilidade disciplinar e aplicar as sanções\ncabíveis, aos militares da Polícia Militar, militares do Corpo de\nBombeiro Militar, membros das carreiras de Polícia Judiciária,\ne membros da carreira de Segurança Penitenciária.\nII. O Conselho de Segurança Pública é órgão com funções\nconsultivas e fiscalizadoras da política de segurança pública.\nIII. O Conselho Estadual de Defesa da Pessoa Humana é\nconstituído por autoridades e por representantes da\ncomunidade, com a incumbência de apurar violação a direitos\nhumanos em todo o território cearense para posterior\nencaminhamento ao Ministério Público, a fim de que seja\npromovida a responsabilidade dos infratores.\nAssinale\nA) se apenas as afirmativas I e II estiverem corretas.\nB) se apenas as afirmativas I e III estiverem corretas.\nC) se apenas as afirmativas II e III estiverem corretas.\nD) se todas as afirmativas estiverem corretas.\nE) se nenhuma afirmativa estiver correta.","item_number":98,"source_pages":[27],"answer_in_official_document":"A","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":true,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":false,"historical_answer_letter":"A","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/9fd7f4dc22f9218916d1374e34427a66ef6de35758ba278356adb92e2295bf1e","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Órgãos de controle e segurança cearenses","observed_style":"lei_estadual_historica","explanation":"O item mistura competências da Controladoria e conselhos estaduais, inclusive limites de apuração de direitos humanos. O texto constitucional estadual atual ainda precisa ser consultado.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","cabecalho_preliminar_em_documento_listado_como_definitivo","fonte_estadual_pendente","escopo_historico_ce","pertinencia_pcac_nao_comprovada"],"primary_evidence":[],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":3,"checked_at":"2026-10-23T00:46:40.968635+00:00","section_heading_ambiguous":true,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[27]},"target_scope":"historico_ce","pcac_compatibility_verified":false,"state_law_currentness_verified":false}}}]$idecan_review_batch$::jsonb) loop
    select * into stored from public.question_corpus_candidates where id=change->>'candidate' for update;
    if not found then raise exception 'Candidato não encontrado; aplique antes o acervo de 200 itens'; end if;
    if stored.content_status=change->>'next_status' and stored.payload=change->'next_payload' then continue; end if;
    if stored.content_status is distinct from change->>'expected_status'
      or stored.payload is distinct from change->'expected_payload' then
      raise exception 'Revisão desatualizada: decisão existente preservada; recarregue o candidato';
    end if;
    if stored.content_status <> 'under_review' then raise exception 'Decisão anterior protegida'; end if;
    if change->'next_payload'->'raw_text' is distinct from stored.payload->'raw_text' then
      raise exception 'Extração original protegida';
    end if;
    if change->'next_payload' ? 'publication'
      or change#>>'{next_payload,individual_review,publication_approved}' is distinct from 'false' then
      raise exception 'Este lote não permite publicação';
    end if;
    insert into public.question_corpus_review_audit(candidate_id,previous_status,next_status,previous_payload,next_payload,reviewer_id)
    values(stored.id,stored.content_status,change->>'next_status',stored.payload,change->'next_payload',auth.uid());
    update public.question_corpus_candidates set content_status=change->>'next_status',payload=change->'next_payload' where id=stored.id;
  end loop;
end $review$;
commit;
-- reviewed significa parecer registrado, não autorização de publicação.
select s.title,c.content_status,count(*) as candidates
from public.question_corpus_sources s join public.question_corpus_candidates c on c.corpus_id=s.id
where s.id in ('56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe','a835d92983601375c77355a50f68bdc77092e4fb88fdb9686ff453b8ed2fd57d')
group by s.title,c.content_status order by s.title,c.content_status;
